mapper.insert:
INSERT INTO TBL_POST ( /* org.bplte.core.api.domain.post.mapper.PostMapper.insertPost */
      OWNER_USER_ID
    , TITLE
    , CONTENT
    , SEARCH_CONTENT
    , INQ_CNT
    , DEL_YN
    , REG_DT
    , RGTR_ID
    , MDFCN_DT
    , MDFR_ID
) VALUES (
      #{ownerUserId}
    , #{title}
    , #{content}
    , #{searchContent}
    , 0
    , 'N'
    , NOW()
    , #{rgtrId}
    , NOW()
    , #{mdfrId}
)

mapper.update:
UPDATE TBL_POST /* org.bplte.core.api.domain.post.mapper.PostMapper.deletePost */
SET DEL_YN = 'Y', MDFCN_DT = NOW(), MDFR_ID = #{mdfrId}
WHERE POST_NUMBER = #{postNumber}

UPDATE TBL_POST /* org.bplte.core.api.domain.post.mapper.PostMapper.updatePost */
SET TITLE = #{title}, CONTENT = #{content}, SEARCH_CONTENT = #{searchContent}, MDFCN_DT = NOW(), MDFR_ID = #{mdfrId}
WHERE POST_NUMBER = #{postNumber}

mapper.select:
SELECT /* org.bplte.core.api.domain.post.mapper.PostMapper.selectPostList */ AA.POST_NUMBER AS postNumber , AA.OWNER_USER_ID AS ownerUserId , AA.TITLE AS title , AA.INQ_CNT AS inqCnt , AA.REG_DT AS regDt , AA.RGTR_ID AS rgtrId , AA.RGTR_NAME AS rgtrName , AA.RGTR_INFO AS rgtrInfo , AA.MDFCN_DT AS mdfcnDt , AA.MDFR_ID AS mdfrId , AA.MDFR_NAME AS mdfrName , AA.MDFR_INFO AS mdfrInfo FROM ( SELECT A.POST_NUMBER AS POST_NUMBER , A.OWNER_USER_ID AS OWNER_USER_ID , A.TITLE AS TITLE , A.INQ_CNT AS INQ_CNT , DATE_FORMAT(A.REG_DT, '%Y-%m-%d %H:%i:%s') AS REG_DT , A.RGTR_ID AS RGTR_ID , B.USER_NAME AS RGTR_NAME , CONCAT(B.USER_NAME, '(', A.RGTR_ID, ')') AS RGTR_INFO , DATE_FORMAT(A.MDFCN_DT, '%Y-%m-%d %H:%i:%s') AS MDFCN_DT , A.MDFR_ID AS MDFR_ID , C.USER_NAME AS MDFR_NAME , CONCAT(C.USER_NAME, '(', A.MDFR_ID, ')') AS MDFR_INFO FROM TBL_POST A INNER JOIN TBL_USER B ON B.USER_ID = A.RGTR_ID INNER JOIN TBL_USER C ON C.USER_ID = A.MDFR_ID WHERE A.DEL_YN = 'N'
) AA
/* Default Sort */ ORDER BY AA.REG_DT DESC, AA.POST_NUMBER DESC
ORDER BY AA.${sortColumnName} ${sortType}
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE TBL_POST /* org.bplte.core.api.domain.post.mapper.PostMapper.updateInquiryCountUp */
SET INQ_CNT = INQ_CNT + 1
WHERE POST_NUMBER = #{postNumber}
